package com.bank.streams;

import org.apache.kafka.common.serialization.Serdes;
import org.apache.kafka.streams.*;
import org.apache.kafka.streams.kstream.*;
import java.util.Properties;
import java.util.logging.*;

public class DescriptionNormalizerApp {
    private static final Logger log = Logger.getLogger(DescriptionNormalizerApp.class.getName());
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    static final String INPUT = "transaction-descriptions-raw";
    static final String OUTPUT = "transaction-descriptions-normalized";

    public static void main(String[] args) {
        // ---- Streams configuration ----
        Properties props = new Properties();
        // application.id names the consumer group AND the internal topics.
        props.put(StreamsConfig.APPLICATION_ID_CONFIG, "description-normalizer");
        props.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "broker1:9092");
        props.put(StreamsConfig.DEFAULT_KEY_SERDE_CLASS_CONFIG, Serdes.String().getClass());
        props.put(StreamsConfig.DEFAULT_VALUE_SERDE_CLASS_CONFIG, Serdes.String().getClass());
        // Make the whole read-process-write atomic (exactly-once).
        props.put(StreamsConfig.PROCESSING_GUARANTEE_CONFIG, StreamsConfig.EXACTLY_ONCE_V2);

        // ---- Build the topology ----
        Topology topology = buildTopology();
        log.info(() -> "Topology:\n" + topology.describe());

        KafkaStreams streams = new KafkaStreams(topology, props);

        // Clean shutdown so the app leaves the group gracefully.
        Runtime.getRuntime().addShutdownHook(new Thread(() -> {
            log.info("Shutting down streams...");
            streams.close();
        }));

        streams.start();
        log.info("Description normalizer started: reading " + INPUT + " → writing " + OUTPUT);
    }

    // Extracted so it can be unit-tested with TopologyTestDriver.
    static Topology buildTopology() {
        StreamsBuilder builder = new StreamsBuilder();

        // 1. SOURCE: read the raw descriptions (key = account, value = description).
        KStream<String, String> raw = builder.stream(INPUT);

        // 2. TRANSFORM: uppercase the VALUE only; key (account) stays the same,
        //    so no repartition and per-account ordering is preserved.
        KStream<String, String> normalized = raw.mapValues(value -> {
            String upper = value == null ? null : value.toUpperCase();
            log.fine(() -> "Normalize '" + value + "' → '" + upper + "'");
            return upper;
        });

        // 3. SINK: write to the normalized topic.
        normalized.to(OUTPUT);

        return builder.build();
    }
}

// ─── Would be in config/BankLogFormatter.java in a real project ───
class BankLogFormatter extends Formatter {
    @Override public String format(LogRecord r) {
        return String.format("%1$tF %1$tT [%2$s] %3$s%n",
                new java.util.Date(r.getMillis()), r.getLevel(), r.getMessage());
    }
}
