package com.bank.streams;

import org.apache.kafka.common.serialization.*;
import org.apache.kafka.streams.*;
import org.junit.jupiter.api.*;
import java.util.Properties;
import static org.junit.jupiter.api.Assertions.*;

class DescriptionNormalizerTopologyTest {
    @Test
    void uppercasesValuesAndKeepsKey() {
        Properties props = new Properties();
        props.put(StreamsConfig.APPLICATION_ID_CONFIG, "test");
        props.put(StreamsConfig.BOOTSTRAP_SERVERS_CONFIG, "dummy:9092");

        try (TopologyTestDriver driver =
                 new TopologyTestDriver(DescriptionNormalizerApp.buildTopology(), props)) {
            var in = driver.createInputTopic(DescriptionNormalizerApp.INPUT,
                new StringSerializer(), new StringSerializer());
            var out = driver.createOutputTopic(DescriptionNormalizerApp.OUTPUT,
                new StringDeserializer(), new StringDeserializer());

            in.pipeInput("SAV2001", "rent credit");   // Rajesh
            in.pipeInput("CUR3001", "Rent Received");  // Priya

            var r1 = out.readKeyValue();
            assertEquals("SAV2001", r1.key);           // key unchanged
            assertEquals("RENT CREDIT", r1.value);     // value uppercased
            var r2 = out.readKeyValue();
            assertEquals("CUR3001", r2.key);
            assertEquals("RENT RECEIVED", r2.value);
        }
    }
}
